    "summaryZh": "2026-08-26 百度热搜第 8 名，热度 723.2万。黄果树景区陡坡塘瀑布上方出现人工喷泉，游客吐槽“5A景区审美太土了”。文旅局回应核查称，该喷泉是陡坡塘夜游表演的配套设施，并非白天常态化景观，白天游览时处于关停状态；为保障夜游表演安全可靠，技术部门每天下午五点后对喷泉设施进行测试，检查设备可靠性、水压和整体效果。",
